window.AUTH=window.AUTH||{};window.AUTH["23-1226"]={"d":"23-1226","id":"2024/23-1226","n":"McLaughlin Chiropractic Associates, Inc. v. McKesson Corporation","briefs":[{"k":"petitioner","label":"Brief of petitioner McLaughlin Chiropractic Associates, Inc.","date":"2024-11-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-1226/332103/20241118151502113_Mclaughlin%20Brief%20for%20Petitioner.pdf","side":"pet","n":72},{"k":"respondent","label":"Brief of respondents McKesson Corporation, et al.","date":"2024-12-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-1226/335535/20241218181553981_McKesson%20Brief%20for%20Respondents.pdf","side":"res","n":76},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2024-12-23","url":"https://www.supremecourt.gov/DocketPDF/23/23-1226/335873/20241223150328280_23-1226bsacUnitedStates.pdf","side":"us","n":74},{"k":"reply","label":"Reply of petitioner McLaughlin Chiropractic Associates, Inc.","date":"2025-01-10","url":"https://www.supremecourt.gov/DocketPDF/23/23-1226/337033/20250110144957896_Reply%20brief%20of%20Petitioner%20.pdf","side":"pet","n":45}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us1r55_3d9g.pdf","tr":true,"items":[{"t":"case","label":"Abbott Laboratories v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"op":6,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"0":"31","1":"44, 45"}},{"t":"case","label":"Adamo Wrecking Co. v. United States","cite":"434 U.S. 275","y":1978,"id":"1977/76-911","sc":1,"op":2,"ar":2,"sum":"The Clean Air Act authorizes the Administrator of the Environmental Protection Agency (EPA) to promulgate \"emission standards\" for hazardous air pollutants. The emission of an air pollutant in violation of an applicable emission standard is prohibited by § 112 (c) (1) (B), the knowing violation of which is made a criminal offense by § 113 (c) (1) (C). Section 307 (b) (1) provides that a petition for review of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27, 36"}},{"t":"case","label":"Air Transport Association v. Public Utility Commission","cite":"833 F.2d 200","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/833/200/","sum":"Holding that an FCC order rejecting a preemption argument deprived the district court of jurisdiction to consider that argument.","sumSrc":"brief:0","by":{"0":"20"}},{"t":"case","label":"Batterton v. Francis","cite":"432 U.S. 416","y":1977,"id":"1976/75-1181","sc":1,"sum":"The regulation is a proper exercise of the Secretary's statutory authority and is reasonable.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Beecham v. United States","cite":"511 U.S. 368","y":1994,"id":"1993/93-445","sc":1,"sum":"The Court applied the choice of law clause to the exemption clause and reasoned that no rights could be restored unless by the jurisdiction that first barred the rights. The Court ruled that though the federal government did not currently have any procedures in place to restore the civil rights of felons, only the federal government had jurisdiction over federal convictions.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Blitz v. Napolitano","cite":"700 F.3d 733","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/700/733/","by":{"0":"5"}},{"t":"case","label":"Bowen v. Michigan Academy of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":2,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29","1":"44","2":"25"}},{"t":"case","label":"Calderon v. Ashmus","cite":"523 U.S. 740","y":1998,"id":"1997/97-391","sc":1,"sum":"The Court held that \"this action for a declaratory judgment and injunctive relief is not a justiciable case within the meaning of Article III.\" \"If the class members file habeas petitions, and the State asserts Chapter 154, the members obviously can litigate California's compliance with Chapter 154 at that time.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Carlton & Harris Chiropractic, Inc. v. PDR Network, LLC","cite":"982 F.3d 258","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/982/258/","sum":"Holding that an FCC order’s “interpretive nature means that the district court was not bound to follow it”.","sumSrc":"brief:0","by":{"0":"40, 41"}},{"t":"case","label":"Carlton & Harris Chiropractic, Inc. v. PDR Network, LLC","cite":"883 F.3d 459","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/459/","by":{"0":"20"}},{"t":"case","label":"-vi- Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"sum":"Petitioner, as a party to numerous Government contracts, was required to comply with Executive Orders 11246 and 11375, which charge the Secretary of Labor with ensuring that corporations that benefit from Government contracts provide equal employment opportunity regardless of race or sex. Regulations promulgated by the Department of Labor's Office of Federal Contract Compliance Programs (OFCCP) require Government …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Chrysler Corp. v. EPA","cite":"600 F.2d 904","y":1979,"url":"https://www.courtlistener.com/c/F.2d/600/904/","op":1,"sum":"Noting that doing so raises a “substantial due process question”.","sumSrc":"brief:0","by":{"0":"36","3":"19"}},{"t":"case","label":"Cohens v. Virginia","cite":"19 U.S. 264","y":1821,"id":"1789-1850/19us264","sc":1,"sum":"The Court decided it had jurisdiction over all cases involving Constitutional questions, including state supreme court decisions.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Committee To Save WEAM v. FCC","cite":"808 F.2d 113","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/808/113/","by":{"0":"14"}},{"t":"case","label":"Direct Marketing Association v. Brohl","cite":"575 U.S. 1","y":2015,"id":"2014/13-1032","sc":1,"sum":"The Court held that the Tax Injunction Act does not prevent federal court review of state tax laws, unless such review could restrict the ability of the state to assess or collect its own taxes.","sumSrc":"Oyez","by":{"0":"23","3":"19"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"0":"24","3":"8"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"sum":"Petitioner accounting firm was retained to audit periodically a brokerage firm's books and records. Respondents, who were customers of the brokerage firm, invested in a securities scheme ultimately revealed as fraudulent and perpetrated by the firm's president and principal stockholder. After the fraud came to light, respondents filed an action for damages against petitioner under § 10 (b) of the Securities Exchange …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"19"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"op":3,"sum":"Describing the 182 McLAUGHLIN CHIROPRACTIC ASSOCIATES, INC. v. McKESSON CORP. Kagan, J., dissenting Hobbs Act's time limit as a “repose provisio[n]”.","sumSrc":"opinion","by":{"0":"22, 24","3":"5, 6, 11"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"op":1,"sum":"The Court held that Section 8(b) of the Real Estate Settlement Procedures Act prohibits a real estate service provider from charging an unearned fee if the fee is divided between two or more parties.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Functional Music, Inc. v. FCC","cite":"274 F.2d 543","y":1958,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/274/543/","by":{"0":"27"}},{"t":"case","label":"Gage v. United States Atomic Energy Commission","cite":"479 F.2d 1214","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/479/1214/","by":{"0":"27"}},{"t":"case","label":"Golan v. FreeEats.com, Inc.","cite":"930 F.3d 950","y":2019,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/930/950/","by":{"0":"41"}},{"t":"case","label":"-vii- Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Gorss Motels, Inc. v. Lands’ End, Inc.","cite":"997 F.3d 470","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/997/470/","sum":"Finding the FCC’s interpretation “persuasive” only after independently interpreting the statutory text.","sumSrc":"brief:0","by":{"0":"41"}},{"t":"case","label":"Gorss Motels, Inc. v. Safemark Systems, LP","cite":"931 F.3d 1094","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/931/1094/","by":{"0":"26, 28, 35, 37","3":"18"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","3":"12"}},{"t":"case","label":"Imhoff Investment, LLC v. Alfoccino, Inc.","cite":"792 F.3d 627","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/627/","by":{"0":"9"}},{"t":"case","label":"Jarecki v. G. D. Searle & Co.","cite":"367 U.S. 303","y":1961,"id":"1960/151","sc":1,"sum":"1. Development of new products is not \"discovery\" within the meaning of § 456 (a) (2) (B) of the Internal Revenue Code of 1939, as amended; and income resulting from the manufacture and sale of certain patented drugs, cameras, camera equipment and stereo products resulting from inventions is not included within the statutory definition of \"abnormal income,\" in § 456 (a), so as to qualify for Korean War excess …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Joseph v. U.S. Civil Service Commission","cite":"554 F.2d 1140","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/554/1140/","by":{"0":"40"}},{"t":"case","label":"Kisor v. Wilkie","cite":"588 U.S. 558","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39, 40"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"0":"28","1":"44"}},{"t":"case","label":"Lyngaas v. Curaden AG","cite":"992 F.3d 412","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/992/412/","by":{"0":"11"}},{"t":"case","label":"Mach Mining, LLC v. E.E.O.C.","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"sum":"The Court held that judicial review of the Equal Employment Opportunity Commission’s efforts at conciliation is appropriate, but such review must be limited to the narrow requirements that Title VII imposes.","sumSrc":"Oyez","by":{"0":"28","1":"44"}},{"t":"case","label":"Mais v. Gulf Coast Collection Bureau","cite":"768 F.3d 1110","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/768/1110/","op":1,"sum":"Holding that a district court “exceed[s] its jurisdiction” if it decides that an FCC order is “inconsistent with the TCPA” even “in a dispute between private parties”.","sumSrc":"brief:0","by":{"0":"20","2":"18"}},{"t":"case","label":"Meyer v. Portfolio Recovery Associates, LLC","cite":"707 F.3d 1036","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/707/1036/","by":{"0":"11"}},{"t":"case","label":"Miller v. FCC","cite":"66 F.3d 1140","y":1995,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/66/1140/","by":{"0":"26"}},{"t":"case","label":"Panzarella v. Navient Solutions, Inc.","cite":"37 F.4th 867","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/37/867/","by":{"0":"41"}},{"t":"case","label":"PDR Network, LLC v. Carlton & Harris Chiropractic","cite":"588 U.S. 1","y":2019,"id":"2018/17-1705","sc":1,"op":1,"sum":"The Court held that Fourth Circuit did not properly consider preliminary issues that determine whether a district court must accept the Federal Communication Commission's legal interpretation of the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"0":"1-3, 7, 15, 16, 18, 20-29, 31-39, 42","1":"2, 25, 27, 37, 38, 41, 42, 43, 47, 49","2":"11, 13, 14, 25, 27, 29","3":"1–4, 7, 15–18, 20"}},{"t":"case","label":"Peretz v. United States","cite":"501 U.S. 923","y":1991,"id":"1990/90-615","sc":1,"sum":"In Gomez v. United States, 490 U. S. 858, this Court held that the selection of a jury in a felony trial without a defendant's consent is not one of the \"additional duties\" that magistrates may be assigned under the Federal Magistrates Act. That decision rested on the lack of both an express statutory provision for de novo review and an explicit congressional intent to permit magistrates to conduct voir dire absent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Perez v. Mortgage Bankers Association","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"sum":"The Court ruled that federal agencies do not need to engage in a notice-and-comment procedure before significantly altering an interpretation of a rule of agency regulation.","sumSrc":"Oyez","by":{"0":"39","1":"50","2":"30, 32","3":"21"}},{"t":"case","label":"Railway Mail Association v. Corsi","cite":"326 U.S. 88","y":1945,"id":"scdb/1944-100","sc":1,"sum":"Section 43 of the New York Civil Rights Law forbids any \"labor organization\" to deny any person membership by reason of his race, color or creed, or to deny any member, by reason of race, color or creed, equal treatment in designation for employment, promotion or dismissal by any employer; other sections prescribe penalties and enforcement procedure. Appellant Railway Mail Association, an organization of regular and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","3":"3"}},{"t":"case","label":"SEC v. Alpine Security Corp.","cite":"308 F. Supp. 3d 775","y":2018,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/308/775/","by":{"0":"32"}},{"t":"case","label":"Shalala v. Guernsey Memorial Hospital","cite":"514 U.S. 87","y":1995,"id":"1994/93-1251","sc":1,"sum":"After the refinancing of its bonded debt resulted in a \"defeasance\" loss for accounting purposes, respondent health care provider (hereinafter Hospital) determined that it was entitled to Medicare reimbursement for part of that loss. Although the Hospital contended that it should receive its full reimbursement in the year of the refinancing, the fiscal intermediary agreed with petitioner Secretary of Health and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","3":"21"}},{"t":"case","label":"True Health Chiropractic, Inc. v. McKesson Corp.","cite":"896 F.3d 923","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/896/923/","op":3,"by":{"0":"12"}},{"t":"case","label":"-ix- United States West Communications, Inc. v. Hamilton","cite":"224 F.3d 1049","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/224/1049/","sum":"Holding that the Hobbs Act “contains no exception for ‘interpretive’ rules, and case law does not create one”.","sumSrc":"brief:0","by":{"0":"2, 13, 19, 38","2":"31"}},{"t":"case","label":"United States National Bank of Oregon v. Independent Insurance Agents of America, Inc.","cite":"508 U.S. 439","y":1993,"id":"1992/92-484","sc":1,"sum":"The Act of Sept. 7, 1916, 39 Stat. 753 (1916 Act), among other things, authorized any national bank doing business in a community with a population not exceeding 5,000 to act as the agent for any insurance company. Although early editions of the United States Code included this provision as section 92 of Title 12 (section 92), the 1952 Code and subsequent editions omitted section 92 with a note indicating that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"United States v. Haggar Apparel Co.","cite":"526 U.S. 380","y":1999,"id":"1998/97-2044","sc":1,"sum":"The Court concluded that the regulation in question was subject to further analysis. Additionally, the Court held that if the regulation was a reasonable interpretation of an ambiguous statutory provision, then it required judicial deference in the Court of International Trade.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"sum":"Title 8 U. S. C. §1324(a)(1)(A)(iv)—which criminalizes “encouraging or inducing” illegal immigration—forbids only the purposeful solicitation and facilitation of specific acts known to violate federal law and is not unconstitutionally overbroad.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24","1":"16"}},{"t":"case","label":"United States v. Mendoza-Lopez","cite":"481 U.S. 828","y":1987,"id":"1986/85-2067","sc":1,"sum":"Title 8 U. S. C. § 1326 provides that any alien who has been deported and thereafter enters the United States is guilty of a felony. Respondents, Mexican nationals, were arrested and deported after a group hearing at which they purportedly waived their rights to apply for suspension of deportation and to appeal. Subsequently, respondents were again arrested in this country and indicted on charges of violating § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36","3":"16"}},{"t":"case","label":"United States v. O’Hagan","cite":"521 U.S. 642","y":1997,"id":"1996/96-842","sc":1,"sum":"The Court ruled that a security-trader who fails to disclose personal profits gained from reliance on exclusive information is guilty of employing \"a deceptive device...in connection with the purchase of a security.\" The security-trader knowingly abuses the duty owed toward the source of information, whether the source is the company he works for or not.","sumSrc":"Oyez","by":{"0":"32","1":"19","3":"17"}},{"t":"case","label":"Vietnam Veterans of America v. Secretary of the Navy","cite":"843 F.2d 528","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/843/528/","sum":"Explaining that, because “valid” means “binding,” it is a “mere tautology” to say that “only [] ‘valid’ legislative rules bind the courts”.","sumSrc":"brief:0","by":{"0":"21, 40"}},{"t":"case","label":"Weyerhaeuser Co. v. U.S. Fish & Wildlife Service","cite":"586 U.S. 9","y":2018,"url":"https://supreme.justia.com/cases/federal/us/586/9/","sc":1,"op":1,"by":{"0":"29","1":"44"}},{"t":"case","label":"Whirlpool Corp. v. Marshall","cite":"445 U.S. 1","y":1980,"id":"1979/78-1870","sc":1,"sum":"The regulation in question was promulgated by respondent in the valid exercise of his authority under the Act, and constitutes a permissible gloss on the Act, in light of the Act's language, structure, and legislative history.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"13"}},{"t":"case","label":"White v. Shalala","cite":"7 F.3d 296","y":1993,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/7/296/","sum":"Noting that an interpretive rule reflects an agency’s “tentative view of the meaning of a particular statutory term”.","sumSrc":"brief:0","by":{"0":"40"}},{"t":"case","label":"Wilson v. A.H. Belo Corp.","cite":"87 F.3d 393","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/87/393/","op":1,"by":{"0":"19","3":"22"}},{"t":"case","label":"-x- Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"op":17,"ar":18,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"0":"34, 35, 36","1":"10, 24, 25, 26, 27, 28, 29, 41, 45, 46","2":"8, 19-21, 26, 29","3":"15"}},{"t":"law","label":"Pub. L. No. 109-21","url":"https://www.govinfo.gov/link/plaw/109/public/21","by":{"0":"5, 9"}},{"t":"law","label":"Pub. L. No. 102-243","url":"https://www.govinfo.gov/link/statute/105/2394","by":{"0":"5","2":"3"}},{"t":"usc","label":"5 U.S.C. § 703","url":"https://www.law.cornell.edu/uscode/text/5/703","stext":{"head":"§703. Form and venue of proceeding","paras":[[0,"The form of proceeding for judicial review is the special statutory review proceeding relevant to the subject matter in a court specified by statute or, in the absence or inadequacy thereof, any applicable form of legal action, including actions for declaratory judgments or writs of prohibitory or mandatory injunction or habeas corpus, in a court of competent jurisdiction. If no special statutory review proceeding is applicable, the action for judicial review may be brought against the United States, the agency by its official title, or the appropriate officer. Except to the extent that prior, adequate, and exclusive opportunity for judicial review is provided by law, agency action is subject to judicial review in civil or criminal proceedings for judicial enforcement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/703?type=usc&year=mostrecent&link-type=html"},"op":15,"ar":3,"head":"§703. Form and venue of proceeding","tname":"Government Organization and Employees","by":{"0":"5, 8, 29","1":"1, 3, 4, 10, 16, 28, 32, 36, 37, 39, 40, 41, 44","2":"15","3":"18"}},{"t":"usc","label":"15 U.S.C. § 78","url":"https://www.law.cornell.edu/uscode/text/15/78","tname":"Commerce and Trade","by":{"0":"31","3":"16, 17"}},{"t":"usc","label":"28 U.S.C. § 2112","url":"https://www.law.cornell.edu/uscode/text/28/2112","subs":["(a)(3)"],"stext":{"head":"§2112. Record on review and enforcement of agency orders","paras":[[0,"(a) The rules prescribed under the authority of section 2072 of this title may provide for the time and manner of filing and the contents of the record in all proceedings instituted in the courts of appeals to enjoin, set aside, suspend, modify, or otherwise review or enforce orders of administrative agencies, boards, commissions, and officers. Such rules may authorize the agency, board, commission, or officer to file in the court a certified list of the materials comprising the record and retain and hold for the court all such materials and transmit the same or any part thereof to the court, when and as required by it, at any time prior to the final determination of the proceeding, and such filing of such certified list of the materials comprising the record and such subsequent transmittal of any such materials when and as required shall be deemed full compliance with any provision of law requiring the filing of the record in the court. The record in such proceedings shall be certified and filed in or held for and transmitted to the court of appeals by the agency, board, commission, or officer concerned within the time and in the manner prescribed by such rules. If proceedings are instituted in two or more courts of appeals with respect to the same order, the following shall apply:"],[1,"(1) If within ten days after issuance of the order the agency, board, commission, or officer concerned receives, from the persons instituting the proceedings, the petition for review with respect to proceedings in at least two courts of appeals, the agency, board, commission, or officer shall proceed in accordance with paragraph (3) of this subsection. If within ten days after the issuance of the order the agency, board, commission, or officer concerned receives, from the persons instituting the proceedings, the petition for review with respect to proceedings in only one court of appeals, the agency, board, commission, or officer shall file the record in that court notwithstanding the institution in any other court of appeals of proceedings for review of that order. In all other cases in which proceedings have been instituted in two or more courts of appeals with respect to the same order, the agency, board, commission, or officer concerned shall file the record in the court in which proceedings with respect to the order were first instituted."],[1,"(2) For purposes of paragraph (1) of this subsection, a copy of the petition or other pleading which institutes proceedings in a court of appeals and which is stamped by the court with the date of filing shall constitute the petition for review. Each agency, board, commission, or officer, as the case may be, shall designate by rule the office and the officer who must receive petitions for review under paragraph (1)."],[1,"(3) If an agency, board, commission, or officer receives two or more petitions for review of an order in accordance with the first sentence of paragraph (1) of this subsection, the agency, board, commission, or officer shall, promptly after the expiration of the ten-day period specified in that sentence, so notify the judicial panel on multidistrict litigation authorized by section 1407 of this title, in such form as that panel shall prescribe. The judicial panel on multidistrict litigation shall, by means of random selection, designate one court of appeals, from among the courts of appeals in which petitions for review have been filed and received within the ten-day period specified in the first sentence of paragraph (1), in which the record is to be filed, and shall issue an order consolidating the petitions for review in that court of appeals. The judicial panel on multidistrict litigation shall, after providing notice to the public and an opportunity for the submission of comments, prescribe rules with respect to the consolidation of proceedings under this paragraph. The agency, board, commission, or officer concerned shall file the record in the court of appeals designated pursuant to this paragraph."],[1,"(4) Any court of appeals in which proceedings with respect to an order of an agency, board, commission, or officer have been instituted may, to the extent authorized by law, stay the effective date of the order. Any such stay may thereafter be modified, revoked, or extended by a court of appeals designated pursuant to paragraph (3) with respect to that order or by any other court of appeals to which the proceedings are transferred."],[1,"(5) All courts in which proceedings are instituted with respect to the same order, other than the court in which the record is filed pursuant to this subsection, shall transfer those proceedings to the court in which the record is so filed. For the convenience of the parties in the interest of justice, the court in which the record is filed may thereafter transfer all the proceedings with respect to that order to any other court of appeals."],[0,"(b) The record to be filed in the court of appeals in such a proceeding shall consist of the order sought to be reviewed or enforced, the findings or report upon which it is based, and the pleadings, evidence, and proceedings before the agency, board, commission, or officer concerned, or such portions thereof (1) as the rules prescribed under the authority of section 2072 of this title may require to be included therein, or (2) as the agency, board, commission, or officer concerned, the petitioner for review or respondent in enforcement, as the case may be, and any intervenor in the court proceeding by written stipulation filed with the agency, board, commission, or officer concerned or in the court in any such proceeding may consistently with the rules prescribed under the authority of section 2072 of this title designate to be included therein, or (3) as the court upon motion of a party or, after a prehearing conference, upon its own motion may by order in any such proceeding designate to be included therein. Such a stipulation or order may provide in an appropriate case that no record need be filed in the court of appeals. If, however, the correctness of a finding of fact by the agency, board, commission, or officer is in question all of the evidence before the agency, board, commission, or officer shall be included in the record except such as the agency, board, commission, or officer concerned, the petitioner for review or respondent in enforcement, as the case may be, and any intervenor in the court proceeding by written stipulation filed with the agency, board, commission, or officer concerned or in the court agree to omit as wholly immaterial to the questioned finding. If there is omitted from the record any portion of the proceedings before the agency, board, commission, or officer which the court subsequently determines to be proper for it to consider to enable it to review or enforce the order in question the court may direct that such additional portion of the proceedings be filed as a supplement to the record. The agency, board, commission, or officer concerned may, at its option and without regard to the foregoing provisions of this subsection, and if so requested by the petitioner for review or respondent in enforcement shall, file in the court the entire record of the proceedings before it without abbreviation."],[0,"(c) The agency, board, commission, or officer concerned may transmit to the court of appeals the original papers comprising the whole or any part of the record or any supplemental record, otherwise true copies of such papers certified by an authorized officer or deputy of the agency, board, commission, or officer concerned shall be transmitted. Any original papers thus transmitted to the court of appeals shall be returned to the agency, board, commission, or officer concerned upon the final determination of the review or enforcement proceeding. Pending such final determination any such papers may be returned by the court temporarily to the custody of the agency, board, commission, or officer concerned if needed for the transaction of the public business. Certified copies of any papers included in the record or any supplemental record may also be returned to the agency, board, commission, or officer concerned upon the final determination of review or enforcement proceedings."],[0,"(d) The provisions of this section are not applicable to proceedings to review decisions of the Tax Court of the United States or to proceedings to review or enforce those orders of administrative agencies, boards, commissions, or officers which are by law reviewable or enforceable by the district courts."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2112?type=usc&year=mostrecent&link-type=html"},"head":"§2112. Record on review and enforcement of agency orders","tname":"Judiciary and Judicial Procedure","by":{"0":"7, 25","1":"1, 4, 33","2":"2"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","subs":["(1)","(2)"],"stext":{"head":"§2342. Jurisdiction of court of appeals","paras":[[0,"The court of appeals (other than the United States Court of Appeals for the Federal Circuit) has exclusive jurisdiction to enjoin, set aside, suspend (in whole or in part), or to determine the validity of—"],[1,"(1) all final orders of the Federal Communication Commission made reviewable by section 402(a) of title 47;"],[1,"(2) all final orders of the Secretary of Agriculture made under chapters 9 and 20A of title 7, except orders issued under sections 210(e), 217a, and 499g(a) of title 7;"],[1,"(3) all rules, regulations, or final orders of—"],[2,"(A) the Secretary of Transportation issued pursuant to section 50501, 50502, 56101–56104, or 57109 of title 46 or pursuant to part B or C of subtitle IV, subchapter III of chapter 311, chapter 313, or chapter 315 of title 49; and"],[2,"(B) the Federal Maritime Commission issued pursuant to section 305,1 41304, 41308, or 41309 or chapter 421 or 441 of title 46;"],[1,"(4) all final orders of the Atomic Energy Commission made reviewable by section 2239 of title 42;"],[1,"(5) all rules, regulations, or final orders of the Surface Transportation Board made reviewable by section 2321 of this title;"],[1,"(6) all final orders under section 812 of the Fair Housing Act; and"],[1,"(7) all final agency actions described in section 20114(c) of title 49."],[0,"Jurisdiction is invoked by filing a petition as provided by section 2344 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2342?type=usc&year=mostrecent&link-type=html"},"op":11,"ar":1,"head":"§2342. Jurisdiction of court of appeals","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 3, 4, 6, 15, 19, 40","1":"1, 4, 5, 9, 12, 14, 17, 19, 32, 33, 37, 45, 47, 49, 31","2":"16, 16, 16","3":"3, 5, 10"}},{"t":"usc","label":"28 U.S.C. § 2343","url":"https://www.law.cornell.edu/uscode/text/28/2343","by":{"0":"7, 25"}},{"t":"usc","label":"28 U.S.C. § 2344","url":"https://www.law.cornell.edu/uscode/text/28/2344","stext":{"head":"§2344. Review of orders; time; notice; contents of petition; service","paras":[[0,"On the entry of a final order reviewable under this chapter, the agency shall promptly give notice thereof by service or publication in accordance with its rules. Any party aggrieved by the final order may, within 60 days after its entry, file a petition to review the order in the court of appeals wherein venue lies. The action shall be against the United States. The petition shall contain a concise statement of—"],[1,"(1) the nature of the proceedings as to which review is sought;"],[1,"(2) the facts on which venue is based;"],[1,"(3) the grounds on which relief is sought; and"],[1,"(4) the relief prayed."],[0,"The petitioner shall attach to the petition, as exhibits, copies of the order, report, or decision of the agency. The clerk shall serve a true copy of the petition on the agency and on the Attorney General by registered mail, with request for a return receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2344?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2344. Review of orders; time; notice; contents of petition; service","tname":"Judiciary and Judicial Procedure","by":{"0":"3, 7, 25","1":"1, 4","2":"16"}},{"t":"usc","label":"28 U.S.C. § 2349","url":"https://www.law.cornell.edu/uscode/text/28/2349","subs":["(a)"],"stext":{"head":"§2349. Jurisdiction of the proceeding","paras":[[0,"(a) The court of appeals has jurisdiction of the proceeding on the filing and service of a petition to review. The court of appeals in which the record on review is filed, on the filing, has jurisdiction to vacate stay orders or interlocutory injunctions previously granted by any court, and has exclusive jurisdiction to make and enter, on the petition, evidence, and proceedings set forth in the record on review, a judgment determining the validity of, and enjoining, setting aside, or suspending, in whole or in part, the order of the agency."],[0,"(b) The filing of the petition to review does not of itself stay or suspend the operation of the order of the agency, but the court of appeals in its discretion may restrain or suspend, in whole or in part, the operation of the order pending the final hearing and determination of the petition. When the petitioner makes application for an interlocutory injunction restraining or suspending the enforcement, operation, or execution of, or setting aside, in whole or in part, any order reviewable under this chapter, at least 5 days' notice of the hearing thereon shall be given to the agency and to the Attorney General. In a case in which irreparable damage would otherwise result to the petitioner, the court of appeals may, on hearing, after reasonable notice to the agency and to the Attorney General, order a temporary stay or suspension, in whole or in part, of the operation of the order of the agency for not more than 60 days from the date of the order pending the hearing on the application for the interlocutory injunction, in which case the order of the court of appeals shall contain a specific finding, based on evidence submitted to the court of appeals, and identified by reference thereto, that irreparable damage would result to the petitioner and specifying the nature of the damage. The court of appeals, at the time of hearing the application for an interlocutory injunction, on a like finding, may continue the temporary stay or suspension, in whole or in part, until decision on the application."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2349?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§2349. Jurisdiction of the proceeding","tname":"Judiciary and Judicial Procedure","by":{"0":"7, 25","1":"4, 9, 14, 17, 18, 44","2":"16, 21, 22, 26","3":"3"}},{"t":"usc","label":"29 U.S.C. § 655","url":"https://www.law.cornell.edu/uscode/text/29/655","stext":{"head":"§655. Standards","paras":[[0,"(a) Promulgation by Secretary of national consensus standards and established Federal standards; time for promulgation; conflicting standards"],[0,"Without regard to chapter 5 of title 5 or to the other subsections of this section, the Secretary shall, as soon as practicable during the period beginning with the effective date of this chapter and ending two years after such date, by rule promulgate as an occupational safety or health standard any national consensus standard, and any established Federal standard, unless he determines that the promulgation of such a standard would not result in improved safety or health for specifically designated employees. In the event of conflict among any such standards, the Secretary shall promulgate the standard which assures the greatest protection of the safety or health of the affected employees."],[0,"(b) Procedure for promulgation, modification, or revocation of standards"],[0,"The Secretary may by rule promulgate, modify, or revoke any occupational safety or health standard in the following manner:"],[0,"(1) Whenever the Secretary, upon the basis of information submitted to him in writing by an interested person, a representative of any organization of employers or employees, a nationally recognized standards-producing organization, the Secretary of Health and Human Services, the National Institute for Occupational Safety and Health, or a State or political subdivision, or on the basis of information developed by the Secretary or otherwise available to him, determines that a rule should be promulgated in order to serve the objectives of this chapter, the Secretary may request the recommendations of an advisory committee appointed under section 656 of this title. The Secretary shall provide such an advisory committee with any proposals of his own or of the Secretary of Health and Human Services, together with all pertinent factual information developed by the Secretary or the Secretary of Health and Human Services, or otherwise available, including the results of research, demonstrations, and experiments. An advisory committee shall submit to the Secretary its recommendations regarding the rule to be promulgated within ninety days from the date of its appointment or within such longer or shorter period as may be prescribed by the Secretary, but in no event for a period which is longer than two hundred and seventy days."],[0,"(2) The Secretary shall publish a proposed rule promulgating, modifying, or revoking an occupational safety or health standard in the Federal Register and shall afford interested persons a period of thirty days after publication to submit written data or comments. Where an advisory committee is appointed and the Secretary determines that a rule should be issued, he shall publish the proposed rule within sixty days after the submission of the advisory committee's recommendations or the expiration of the period prescribed by the Secretary for such submission."],[0,"(3) On or before the last day of the period provided for the submission of written data or comments under paragraph (2), any interested person may file with the Secretary written objections to the proposed rule, stating the grounds therefor and requesting a public hearing on such objections. Within thirty days after the last day for filing such objections, the Secretary shall publish in the Federal Register a notice specifying the occupational safety or health standard to which objections have been filed and a hearing requested, and specifying a time and place for such hearing."],[0,"(4) Within sixty days after the expiration of the period provided for the submission of written data or comments under paragraph (2), or within sixty days after the completion of any hearing held under paragraph (3), the Secretary shall issue a rule promulgating, modifying, or revoking an occupational safety or health standard or make a determination that a rule should not be issued. Such a rule may contain a provision delaying its effective date for such period (not in excess of ninety days) as the Secretary determines may be necessary to insure that affected employers and employees will be informed of the existence of the standard and of its terms and that employers affected are given an opportunity to familiarize themselves and their employees with the existence of the requirements of the standard."],[0,"(5) The Secretary, in promulgating standards dealing with toxic materials or harmful physical agents under this subsection, shall set the standard which most adequately assures, to the extent feasible, on the basis of the best available evidence, that no employee will suffer material impairment of health or functional capacity even if such employee has regular exposure to the hazard dealt with by such standard for the period of his working life. Development of standards under this subsection shall be based upon research, demonstrations, experiments, and such other information as may be appropriate. In addition to the attainment of the highest degree of health and safety protection for the employee, other considerations shall be the latest available scientific data in the field, the feasibility of the standards, and experience gained under this and other health and safety laws. Whenever practicable, the standard promulgated shall be expressed in terms of objective criteria and of the performance desired."],[0,"(6)(A) Any employer may apply to the Secretary for a temporary order granting a variance from a standard or any provision thereof promulgated under this section. Such temporary order shall be granted only if the employer files an application which meets the requirements of clause (B) and establishes that (i) he is unable to comply with a standard by its effective date because of unavailability of professional or technical personnel or of materials and equipment needed to come into compliance with the standard or because necessary construction or alteration of facilities cannot be completed by the effective date, (ii) he is taking all available steps to safeguard his employees against the hazards covered by the standard, and (iii) he has an effective program for coming into compliance with the standard as quickly as practicable. Any temporary order issued under this paragraph shall prescribe the practices, means, methods, operations, and processes which the employer must adopt and use while the order is in effect and state in detail his program for coming into compliance with the standard. Such a temporary order may be granted only after notice to employees and an opportunity for a hearing: Provided, That the Secretary may issue one interim order to be effective until a decision is made on the basis of the hearing. No temporary order may be in effect for longer than the period needed by the employer to achieve compliance with the standard or one year, whichever is shorter, except that such an order may be renewed not more than twice (I) so long as the requirements of this paragraph are met and (II) if an application for renewal is filed at least 90 days prior to the expiration date of the order. No interim renewal of an order may remain in effect for longer than 180 days."],[0,"(B) An application for a temporary order under this paragraph (6) shall contain:"],[1,"(i) a specification of the standard or portion thereof from which the employer seeks a variance,"],[1,"(ii) a representation by the employer, supported by representations from qualified persons having firsthand knowledge of the facts represented, that he is unable to comply with the standard or portion thereof and a detailed statement of the reasons therefor,"],[1,"(iii) a statement of the steps he has taken and will take (with specific dates) to protect employees against the hazard covered by the standard,"],[1,"(iv) a statement of when he expects to be able to comply with the standard and what steps he has taken and what steps he will take (with dates specified) to come into compliance with the standard, and"],[1,"(v) a certification that he has informed his employees of the application by giving a copy thereof to their authorized representative, posting a statement giving a summary of the application and specifying where a copy may be examined at the place or places where notices to employees are normally posted, and by other appropriate means."],[0,"A description of how employees have been informed shall be contained in the certification. The information to employees shall also inform them of their right to petition the Secretary for a hearing."],[0,"(C) The Secretary is authorized to grant a variance from any standard or portion thereof whenever he determines, or the Secretary of Health and Human Services certifies, that such variance is necessary to permit an employer to participate in an experiment approved by him or the Secretary of Health and Human Services designed to demonstrate or validate new and improved techniques to safeguard the health or safety of workers."],[0,"(7) Any standard promulgated under this subsection shall prescribe the use of labels or other appropriate forms of warning as are necessary to insure that employees are apprised of all hazards to which they are exposed, relevant symptoms and appropriate emergency treatment, and proper conditions and precautions of safe use or exposure. Where appropriate, such standard shall also prescribe suitable protective equipment and control or technological procedures to be used in connection with such hazards and shall provide for monitoring or measuring employee exposure at such locations and intervals, and in such manner as may be necessary for the protection of employees. In addition, where appropriate, any such standard shall prescribe the type and frequency of medical examinations or other tests which shall be made available, by the employer or at his cost, to employees exposed to such hazards in order to most effectively determine whether the health of such employees is adversely affected by such exposure. In the event such medical examinations are in the nature of research, as determined by the Secretary of Health and Human Services, such examinations may be furnished at the expense of the Secretary of Health and Human Services. The results of such examinations or tests shall be furnished only to the Secretary or the Secretary of Health and Human Services, and, at the request of the employee, to his physician. The Secretary, in consultation with the Secretary of Health and Human Services, may by rule promulgated pursuant to section 553 of title 5, make appropriate modifications in the foregoing requirements relating to the use of labels or other forms of warning, monitoring or measuring, and medical examinations, as may be warranted by experience, information, or medical or technological developments acquired subsequent to the promulgation of the relevant standard."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/655?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§655. Standards","tname":"Labor","by":{"0":"31, 32","1":"19","3":"17"}},{"t":"usc","label":"33 U.S.C. § 1369","url":"https://www.law.cornell.edu/uscode/text/33/1369","subs":["(b)(2)"],"stext":{"head":"§1369. Administrative procedure and judicial review","paras":[[0,"(a) Subpenas"],[0,"(1) For purposes of obtaining information under section 1315 of this title, or carrying out section 1367(e) of this title, the Administrator may issue subpenas for the attendance and testimony of witnesses and the production of relevant papers, books, and documents, and he may administer oaths. Except for effluent data, upon a showing satisfactory to the Administrator that such papers, books, documents, or information or particular part thereof, if made public, would divulge trade secrets or secret processes, the Administrator shall consider such record, report, or information or particular portion thereof confidential in accordance with the purposes of section 1905 of title 18, except that such paper, book, document, or information may be disclosed to other officers, employees, or authorized representatives of the United States concerned with carrying out this chapter, or when relevant in any proceeding under this chapter. Witnesses summoned shall be paid the same fees and mileage that are paid witnesses in the courts of the United States. In case of contumacy or refusal to obey a subpena served upon any person under this subsection, the district court of the United States for any district in which such person is found or resides or transacts business, upon application by the United States and after notice to such person, shall have jurisdiction to issue an order requiring such person to appear and give testimony before the Administrator, to appear and produce papers, books, and documents before the Administrator, or both, and any failure to obey such order of the court may be punished by such court as a contempt thereof."],[0,"(2) The district courts of the United States are authorized, upon application by the Administrator, to issue subpenas for attendance and testimony of witnesses and the production of relevant papers, books, and documents, for purposes of obtaining information under sections 1314(b) and (c) of this title. Any papers, books, documents, or other information or part thereof, obtained by reason of such a subpena shall be subject to the same requirements as are provided in paragraph (1) of this subsection."],[0,"(b) Review of Administrator's actions; selection of court; fees"],[0,"(1) Review of the Administrator's action (A) in promulgating any standard of performance under section 1316 of this title, (B) in making any determination pursuant to section 1316(b)(1)(C) of this title, (C) in promulgating any effluent standard, prohibition, or pretreatment standard under section 1317 of this title, (D) in making any determination as to a State permit program submitted under section 1342(b) of this title, (E) in approving or promulgating any effluent limitation or other limitation under section 1311, 1312, 1316, or 1345 of this title, (F) in issuing or denying any permit under section 1342 of this title, and (G) in promulgating any individual control strategy under section 1314(l) of this title, may be had by any interested person in the Circuit Court of Appeals of the United States for the Federal judicial district in which such person resides or transacts business which is directly affected by such action upon application by such person. Any such application shall be made within 120 days from the date of such determination, approval, promulgation, issuance or denial, or after such date only if such application is based solely on grounds which arose after such 120th day."],[0,"(2) Action of the Administrator with respect to which review could have been obtained under paragraph (1) of this subsection shall not be subject to judicial review in any civil or criminal proceeding for enforcement."],[0,"(3) Award of fees.—In any judicial proceeding under this subsection, the court may award costs of litigation (including reasonable attorney and expert witness fees) to any prevailing or substantially prevailing party whenever it determines that such award is appropriate."],[0,"(4) Discharges incidental to normal operation of vessels.—"],[1,"(A) In general.—Except as provided in subparagraph (B), any interested person may file a petition for review of a final agency action under section 1322(p) of this title of the Administrator or the Secretary of the department in which the Coast Guard is operating in accordance with the requirements of this subsection."],[1,"(B) Venue exception.—Subject to section 1322(p)(7)(C)(v) of this title, a petition for review of a final agency action under section 1322(p) of this title of the Administrator or the Secretary of the department in which the Coast Guard is operating may be filed only in the United States Court of Appeals for the District of Columbia Circuit."],[0,"(c) Additional evidence"],[0,"In any judicial proceeding brought under subsection (b) of this section in which review is sought of a determination under this chapter required to be made on the record after notice and opportunity for hearing, if any party applies to the court for leave to adduce additional evidence, and shows to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Administrator, the court may order such additional evidence (and evidence in rebuttal thereof) to be taken before the Administrator, in such manner and upon such terms and conditions as the court may deem proper. The Administrator may modify his findings as to the facts, or make new findings, by reason of the additional evidence so taken and he shall file such modified or new findings, and his recommendation, if any, for the modification or setting aside of his original determination, with the return of such additional evidence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1369?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1369. Administrative procedure and judicial review","tname":"Navigation and Navigable Waters","by":{"0":"33","1":"39","2":"27","3":"1"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","by":{"0":"33","1":"39"}},{"t":"usc","label":"42 U.S.C. § 9613","url":"https://www.law.cornell.edu/uscode/text/42/9613","stext":{"head":"§9613. Civil proceedings","paras":[[0,"(a) Review of regulations in Circuit Court of Appeals of the United States for the District of Columbia"],[0,"Review of any regulation promulgated under this chapter may be had upon application by any interested person only in the Circuit Court of Appeals of the United States for the District of Columbia. Any such application shall be made within ninety days from the date of promulgation of such regulations. Any matter with respect to which review could have been obtained under this subsection shall not be subject to judicial review in any civil or criminal proceeding for enforcement or to obtain damages or recovery of response costs."],[0,"(b) Jurisdiction; venue"],[0,"Except as provided in subsections (a) and (h) of this section, the United States district courts shall have exclusive original jurisdiction over all controversies arising under this chapter, without regard to the citizenship of the parties or the amount in controversy. Venue shall lie in any district in which the release or damages occurred, or in which the defendant resides, may be found, or has his principal office. For the purposes of this section, the Fund shall reside in the District of Columbia."],[0,"(c) Controversies or other matters resulting from tax collection or tax regulation review"],[0,"The provisions of subsections (a) and (b) of this section shall not apply to any controversy or other matter resulting from the assessment of collection of any tax, as provided by subchapter II 1 of this chapter, or to the review of any regulation promulgated under title 26."],[0,"(d) Litigation commenced prior to December 11, 1980"],[0,"No provision of this chapter shall be deemed or held to moot any litigation concerning any release of any hazardous substance, or any damages associated therewith, commenced prior to December 11, 1980."],[0,"(e) Nationwide service of process"],[0,"In any action by the United States under this chapter, process may be served in any district where the defendant is found, resides, transacts business, or has appointed an agent for the service of process."],[0,"(f) Contribution"],[0,"(1) Contribution"],[1,"Any person may seek contribution from any other person who is liable or potentially liable under section 9607(a) of this title, during or following any civil action under section 9606 of this title or under section 9607(a) of this title. Such claims shall be brought in accordance with this section and the Federal Rules of Civil Procedure, and shall be governed by Federal law. In resolving contribution claims, the court may allocate response costs among liable parties using such equitable factors as the court determines are appropriate. Nothing in this subsection shall diminish the right of any person to bring an action for contribution in the absence of a civil action under section 9606 of this title or section 9607 of this title."],[0,"(2) Settlement"],[1,"A person who has resolved its liability to the United States or a State in an administrative or judicially approved settlement shall not be liable for claims for contribution regarding matters addressed in the settlement. Such settlement does not discharge any of the other potentially liable persons unless its terms so provide, but it reduces the potential liability of the others by the amount of the settlement."],[0,"(3) Persons not party to settlement"],[1,"(A) If the United States or a State has obtained less than complete relief from a person who has resolved its liability to the United States or the State in an administrative or judicially approved settlement, the United States or the State may bring an action against any person who has not so resolved its liability."],[1,"(B) A person who has resolved its liability to the United States or a State for some or all of a response action or for some or all of the costs of such action in an administrative or judicially approved settlement may seek contribution from any person who is not party to a settlement referred to in paragraph (2)."],[1,"(C) In any action under this paragraph, the rights of any person who has resolved its liability to the United States or a State shall be subordinate to the rights of the United States or the State. Any contribution action brought under this paragraph shall be governed by Federal law."],[0,"(g) Period in which action may be brought"],[0,"(1) Actions for natural resource damages"],[1,"Except as provided in paragraphs (3) and (4), no action may be commenced for damages (as defined in section 9601(6) of this title) under this chapter, unless that action is commenced within 3 years after the later of the following:"],[2,"(A) The date of the discovery of the loss and its connection with the release in question."],[2,"(B) The date on which regulations are promulgated under section 9651(c) of this title."],[1,"With respect to any facility listed on the National Priorities List (NPL), any Federal facility identified under section 9620 of this title (relating to Federal facilities), or any vessel or facility at which a remedial action under this chapter is otherwise scheduled, an action for damages under this chapter must be commenced within 3 years after the completion of the remedial action (excluding operation and maintenance activities) in lieu of the dates referred to in subparagraph (A) or (B). In no event may an action for damages under this chapter with respect to such a vessel or facility be commenced (i) prior to 60 days after the Federal or State natural resource trustee provides to the President and the potentially responsible party a notice of intent to file suit, or (ii) before selection of the remedial action if the President is diligently proceeding with a remedial investigation and feasibility study under section 9604(b) of this title or section 9620 of this title (relating to Federal facilities). The limitation in the preceding sentence on commencing an action before giving notice or before selection of the remedial action does not apply to actions filed on or before October 17, 1986."],[0,"(2) Actions for recovery of costs"],[1,"An initial action for recovery of the costs referred to in section 9607 of this title must be commenced—"],[2,"(A) for a removal action, within 3 years after completion of the removal action, except that such cost recovery action must be brought within 6 years after a determination to grant a waiver under section 9604(c)(1)(C) of this title for continued response action; and"],[2,"(B) for a remedial action, within 6 years after initiation of physical on-site construction of the remedial action, except that, if the remedial action is initiated within 3 years after the completion of the removal action, costs incurred in the removal action may be recovered in the cost recovery action brought under this subparagraph."],[1,"In any such action described in this subsection, the court shall enter a declaratory judgment on liability for response costs or damages that will be binding on any subsequent action or actions to recover further response costs or damages. A subsequent action or actions under section 9607 of this title for further response costs at the vessel or facility may be maintained at any time during the response action, but must be commenced no later than 3 years after the date of completion of all response action. Except as otherwise provided in this paragraph, an action may be commenced under section 9607 of this title for recovery of costs at any time after such costs have been incurred."],[0,"(3) Contribution"],[1,"No action for contribution for any response costs or damages may be commenced more than 3 years after—"],[2,"(A) the date of judgment in any action under this chapter for recovery of such costs or damages, or"],[2,"(B) the date of an administrative order under section 9622(g) of this title (relating to de minimis settlements) or 9622(h) of this title (relating to cost recovery settlements) or entry of a judicially approved settlement with respect to such costs or damages."],[0,"(4) Subrogation"],[1,"No action based on rights subrogated pursuant to this section by reason of payment of a claim may be commenced under this subchapter more than 3 years after the date of payment of such claim."],[0,"(5) Actions to recover indemnification payments"],[1,"Notwithstanding any other provision of this subsection, where a payment pursuant to an indemnification agreement with a response action contractor is made under section 9619 of this title, an action under section 9607 of this title for recovery of such indemnification payment from a potentially responsible party may be brought at any time before the expiration of 3 years from the date on which such payment is made."],[0,"(6) Minors and incompetents"],[1,"The time limitations contained herein shall not begin to run—"],[2,"(A) against a minor until the earlier of the date when such minor reaches 18 years of age or the date on which a legal representative is duly appointed for such minor, or"],[2,"(B) against an incompetent person until the earlier of the date on which such incompetent's incompetency ends or the date on which a legal representative is duly appointed for such incompetent."],[0,"(h) Timing of review"],[0,"No Federal court shall have jurisdiction under Federal law other than under section 1332 of title 28 (relating to diversity of citizenship jurisdiction) or under State law which is applicable or relevant and appropriate under section 9621 of this title (relating to cleanup standards) to review any challenges to removal or remedial action selected under section 9604 of this title, or to review any order issued under section 9606(a) of this title, in any action except one of the following:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9613?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9613. Civil proceedings","tname":"The Public Health and Welfare","by":{"0":"33","1":"39"}},{"t":"usc","label":"47 U.S.C. § 227","url":"https://www.law.cornell.edu/uscode/text/47/227","subs":["(a)","(b)","(d)","(a)(3)","(b)(1)(C)","(b)(2)","(b)(3)","(c)(5)"],"stext":{"head":"§227. Restrictions on use of telephone equipment","paras":[[0,"(a) Definitions"],[0,"As used in this section—"],[1,"(1) The term \"automatic telephone dialing system\" means equipment which has the capacity—"],[2,"(A) to store or produce telephone numbers to be called, using a random or sequential number generator; and"],[2,"(B) to dial such numbers."],[1,"(2) The term \"established business relationship\", for purposes only of subsection (b)(1)(C)(i), shall have the meaning given the term in section 64.1200 of title 47, Code of Federal Regulations, as in effect on January 1, 2003, except that—"],[2,"(A) such term shall include a relationship between a person or entity and a business subscriber subject to the same terms applicable under such section to a relationship between a person or entity and a residential subscriber; and"],[2,"(B) an established business relationship shall be subject to any time limitation established pursuant to paragraph (2)(G)).1"],[1,"(3) The term \"telephone facsimile machine\" means equipment which has the capacity (A) to transcribe text or images, or both, from paper into an electronic signal and to transmit that signal over a regular telephone line, or (B) to transcribe text or images (or both) from an electronic signal received over a regular telephone line onto paper."],[1,"(4) The term \"telephone solicitation\" means the initiation of a telephone call or message for the purpose of encouraging the purchase or rental of, or investment in, property, goods, or services, which is transmitted to any person, but such term does not include a call or message (A) to any person with that person's prior express invitation or permission, (B) to any person with whom the caller has an established business relationship, or (C) by a tax exempt nonprofit organization."],[1,"(5) The term \"unsolicited advertisement\" means any material advertising the commercial availability or quality of any property, goods, or services which is transmitted to any person without that person's prior express invitation or permission, in writing or otherwise."],[0,"(b) Restrictions on use of automated telephone equipment"],[0,"(1) Prohibitions"],[1,"It shall be unlawful for any person within the United States, or any person outside the United States if the recipient is within the United States—"],[2,"(A) to make any call (other than a call made for emergency purposes or made with the prior express consent of the called party) using any automatic telephone dialing system or an artificial or prerecorded voice—"],[3,"(i) to any emergency telephone line (including any \"911\" line and any emergency line of a hospital, medical physician or service office, health care facility, poison control center, or fire protection or law enforcement agency);"],[3,"(ii) to the telephone line of any guest room or patient room of a hospital, health care facility, elderly home, or similar establishment; or"],[3,"(iii) to any telephone number assigned to a paging service, cellular telephone service, specialized mobile radio service, or other radio common carrier service, or any service for which the called party is charged for the call, unless such call is made solely to collect a debt owed to or guaranteed by the United States;"],[2,"(B) to initiate any telephone call to any residential telephone line using an artificial or prerecorded voice to deliver a message without the prior express consent of the called party, unless the call is initiated for emergency purposes, is made solely pursuant to the collection of a debt owed to or guaranteed by the United States, or is exempted by rule or order by the Commission under paragraph (2)(B);"],[2,"(C) to use any telephone facsimile machine, computer, or other device to send, to a telephone facsimile machine, an unsolicited advertisement, unless—"],[3,"(i) the unsolicited advertisement is from a sender with an established business relationship with the recipient;"],[3,"(ii) the sender obtained the number of the telephone facsimile machine through—"],[4,"(I) the voluntary communication of such number, within the context of such established business relationship, from the recipient of the unsolicited advertisement, or"],[4,"(II) a directory, advertisement, or site on the Internet to which the recipient voluntarily agreed to make available its facsimile number for public distribution,"],[0,"except that this clause shall not apply in the case of an unsolicited advertisement that is sent based on an established business relationship with the recipient that was in existence before July 9, 2005, if the sender possessed the facsimile machine number of the recipient before July 9, 2005; and"],[3,"(iii) the unsolicited advertisement contains a notice meeting the requirements under paragraph (2)(D),"],[2,"except that the exception under clauses (i) and (ii) shall not apply with respect to an unsolicited advertisement sent to a telephone facsimile machine by a sender to whom a request has been made not to send future unsolicited advertisements to such telephone facsimile machine that complies with the requirements under paragraph (2)(E); or"],[2,"(D) to use an automatic telephone dialing system in such a way that two or more telephone lines of a multi-line business are engaged simultaneously."],[0,"(2) Regulations; exemptions and other provisions"],[1,"The Commission shall prescribe regulations to implement the requirements of this subsection. In implementing the requirements of this subsection, the Commission—"],[2,"(A) shall consider prescribing regulations to allow businesses to avoid receiving calls made using an artificial or prerecorded voice to which they have not given their prior express consent;"],[2,"(B) may, by rule or order, exempt from the requirements of paragraph (1)(B) of this subsection, subject to such conditions as the Commission may prescribe—"],[3,"(i) calls that are not made for a commercial purpose; and"],[3,"(ii) such classes or categories of calls made for commercial purposes as the Commission determines—"],[4,"(I) will not adversely affect the privacy rights that this section is intended to protect; and"],[4,"(II) do not include the transmission of any unsolicited advertisement;"],[2,"(C) may, by rule or order, exempt from the requirements of paragraph (1)(A)(iii) of this subsection calls to a telephone number assigned to a cellular telephone service that are not charged to the called party, subject to such conditions as the Commission may prescribe as necessary in the interest of the privacy rights this section is intended to protect;"],[2,"(D) shall provide that a notice contained in an unsolicited advertisement complies with the requirements under this subparagraph only if—"],[3,"(i) the notice is clear and conspicuous and on the first page of the unsolicited advertisement;"],[3,"(ii) the notice states that the recipient may make a request to the sender of the unsolicited advertisement not to send any future unsolicited advertisements to a telephone facsimile machine or machines and that failure to comply, within the shortest reasonable time, as determined by the Commission, with such a request meeting the requirements under subparagraph (E) is unlawful;"],[3,"(iii) the notice sets forth the requirements for a request under subparagraph (E);"],[3,"(iv) the notice includes—"],[4,"(I) a domestic contact telephone and facsimile machine number for the recipient to transmit such a request to the sender; and"],[4,"(II) a cost-free mechanism for a recipient to transmit a request pursuant to such notice to the sender of the unsolicited advertisement; the Commission shall by rule require the sender to provide such a mechanism and may, in the discretion of the Commission and subject to such conditions as the Commission may prescribe, exempt certain classes of small business senders, but only if the Commission determines that the costs to such class are unduly burdensome given the revenues generated by such small businesses;"],[3,"(v) the telephone and facsimile machine numbers and the cost-free mechanism set forth pursuant to clause (iv) permit an individual or business to make such a request at any time on any day of the week; and"],[3,"(vi) the notice complies with the requirements of subsection (d);"],[2,"(E) shall provide, by rule, that a request not to send future unsolicited advertisements to a telephone facsimile machine complies with the requirements under this subparagraph only if—"],[3,"(i) the request identifies the telephone number or numbers of the telephone facsimile machine or machines to which the request relates;"],[3,"(ii) the request is made to the telephone or facsimile number of the sender of such an unsolicited advertisement provided pursuant to subparagraph (D)(iv) or by any other method of communication as determined by the Commission; and"],[3,"(iii) the person making the request has not, subsequent to such request, provided express invitation or permission to the sender, in writing or otherwise, to send such advertisements to such person at such telephone facsimile machine;"],[2,"(F) may, in the discretion of the Commission and subject to such conditions as the Commission may prescribe, allow professional or trade associations that are tax-exempt nonprofit organizations to send unsolicited advertisements to their members in furtherance of the association's tax-exempt purpose that do not contain the notice required by paragraph (1)(C)(iii), except that the Commission may take action under this subparagraph only—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/227?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§227. Restrictions on use of telephone equipment","tname":"Telecommunications","by":{"0":"5, 9, 10, 12","1":"5, 6, 52, 5, 6, 33, 49, 51, 52, 53","2":"3, 3, 3, 4, 4"}},{"t":"usc","label":"47 U.S.C. § 402","url":"https://www.law.cornell.edu/uscode/text/47/402","subs":["(a)"],"stext":{"head":"§402. Judicial review of Commission's orders and decisions","paras":[[0,"(a) Procedure"],[0,"Any proceeding to enjoin, set aside, annul, or suspend any order of the Commission under this chapter (except those appealable under subsection (b) of this section) shall be brought as provided by and in the manner prescribed in chapter 158 of title 28."],[0,"(b) Right to appeal"],[0,"Appeals may be taken from decisions and orders of the Commission to the United States Court of Appeals for the District of Columbia in any of the following cases:"],[1,"(1) By any applicant for a construction permit or station license, whose application is denied by the Commission."],[1,"(2) By any applicant for the renewal or modification of any such instrument of authorization whose application is denied by the Commission."],[1,"(3) By any party to an application for authority to transfer, assign, or dispose of any such instrument of authorization, or any rights thereunder, whose application is denied by the Commission."],[1,"(4) By any applicant for the permit required by section 325 of this title whose application has been denied by the Commission, or by any permittee under said section whose permit has been revoked by the Commission."],[1,"(5) By the holder of any construction permit or station license which has been modified or revoked by the Commission."],[1,"(6) By any other person who is aggrieved or whose interests are adversely affected by any order of the Commission granting or denying any application described in paragraphs (1), (2), (3), (4), and (9) of this subsection."],[1,"(7) By any person upon whom an order to cease and desist has been served under section 312 of this title."],[1,"(8) By any radio operator whose license has been suspended by the Commission."],[1,"(9) By any applicant for authority to provide interLATA services under section 271 of this title whose application is denied by the Commission."],[1,"(10) By any person who is aggrieved or whose interests are adversely affected by a determination made by the Commission under section 618(a)(3) of this title."],[0,"(c) Filing notice of appeal; contents; jurisdiction; temporary orders"],[0,"Such appeal shall be taken by filing a notice of appeal with the court within thirty days from the date upon which public notice is given of the decision or order complained of. Such notice of appeal shall contain a concise statement of the nature of the proceedings as to which the appeal is taken; a concise statement of the reasons on which the appellant intends to rely, separately stated and numbered; and proof of service of a true copy of said notice and statement upon the Commission. Upon filing of such notice, the court shall have jurisdiction of the proceedings and of the questions determined therein and shall have power, by order, directed to the Commission or any other party to the appeal, to grant such temporary relief as it may deem just and proper. Orders granting temporary relief may be either affirmative or negative in their scope and application so as to permit either the maintenance of the status quo in the matter in which the appeal is taken or the restoration of a position or status terminated or adversely affected by the order appealed from and shall, unless otherwise ordered by the court, be effective pending hearing and determination of said appeal and compliance by the Commission with the final judgment of the court rendered in said appeal."],[0,"(d) Notice to interested parties; filing of record"],[0,"Upon the filing of any such notice of appeal the appellant shall, not later than five days after the filing of such notice, notify each person shown by the records of the Commission to be interested in said appeal of the filing and pendency of the same. The Commission shall file with the court the record upon which the order complained of was entered, as provided in section 2112 of title 28."],[0,"(e) Intervention"],[0,"Within thirty days after the filing of any such appeal any interested person may intervene and participate in the proceedings had upon said appeal by filing with the court a notice of intention to intervene and a verified statement showing the nature of the interest of such party, together with proof of service of true copies of said notice and statement, both upon appellant and upon the Commission. Any person who would be aggrieved or whose interest would be adversely affected by a reversal or modification of the order of the Commission complained of shall be considered an interested party."],[0,"(f) Records and briefs"],[0,"The record and briefs upon which any such appeal shall be heard and determined by the court shall contain such information and material, and shall be prepared within such time and in such manner as the court may by rule prescribe."],[0,"(g) Time of hearing; procedure"],[0,"The court shall hear and determine the appeal upon the record before it in the manner prescribed by section 706 of title 5."],[0,"(h) Remand"],[0,"In the event that the court shall render a decision and enter an order reversing the order of the Commission, it shall remand the case to the Commission to carry out the judgment of the court and it shall be the duty of the Commission, in the absence of the proceedings to review such judgment, to forthwith give effect thereto, and unless otherwise ordered by the court, to do so upon the basis of the proceedings already had and the record upon which said appeal was heard and determined."],[0,"(i) Judgment for costs"],[0,"The court may, in its discretion, enter judgment for costs in favor of or against an appellant, or other interested parties intervening in said appeal, but not against the Commission, depending upon the nature of the issues involved upon said appeal and the outcome thereof."],[0,"(j) Finality of decision; review by Supreme Court"],[0,"The court's judgment shall be final, subject, however, to review by the Supreme Court of the United States upon writ of certiorari on petition therefor under section 1254 of title 28, by the appellant, by the Commission, or by any interested party intervening in the appeal, or by certification by the court pursuant to the provisions of that section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/402?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§402. Judicial review of Commission's orders and decisions","tname":"Telecommunications","by":{"0":"6","1":"4, 9, 15, 18, 47","2":"4"}},{"t":"reg","label":"47 C.F.R. § 1.102","url":"https://www.ecfr.gov/current/title-47/section-1.102","by":{"0":"14"}},{"t":"case","label":"Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"ar":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Bouarfa v. Mayorkas","cite":"604 U.S. __","y":2024,"id":"2024/23-583","sc":1,"op":1,"sum":"The Court held that revocation of an approved visa petition under 8 U.S.C. §1155 based on a sham-marriage determination by the Secretary of Homeland Security is the kind of discretionary decision that falls within the purview of §1252(a)(2)(B)(ii), which strips federal courts of jurisdiction to review certain actions “in the discretion of” the agency.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48, 50"}},{"t":"case","label":"Brown v. Davenport","cite":"596 U.S. 118","y":2022,"id":"2021/20-826","sc":1,"sum":"When a state court has ruled on the merits of a state prisoner’s claim, a federal court cannot grant habeas relief without applying both the test this Court outlined in Brecht v. Abrahamson, 507 U. S. 619, and the one Congress prescribed in the Antiterrorism and Effective Death Penalty Act of 1996; the Sixth Circuit erred in granting habeas relief to Mr. Davenport based solely on its assessment that he could satisfy the Brecht standard.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"28"}},{"t":"case","label":"Career Counseling, Inc. v. AmeriFactors Fin. Grp.","cite":"91 F.4th 202","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/91/202/","by":{"1":"51, 53"}},{"t":"case","label":"Christopher v. SmithKline Beecham","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"op":1,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Corner Post v. Bd. of Govs. of Fed. Reserve Sys.","cite":"603 U.S. 799","y":2024,"url":"https://supreme.justia.com/cases/federal/us/603/799/","sc":1,"op":4,"ar":4,"sum":"Describing the 182 McLAUGHLIN CHIROPRACTIC ASSOCIATES, INC. v. McKESSON CORP. Kagan, J., dissenting Hobbs Act's time limit as a “repose provisio[n]”.","sumSrc":"opinion","by":{"1":"4, 5, 17, 33, 34, 43"}},{"t":"case","label":"ix FCC v. ITT World Comms.","cite":"466 U.S. 463","y":1984,"id":"1983/83-371","sc":1,"op":4,"ar":2,"sum":"The Government in the Sunshine Act, 5 U. S. C. §552b(b), requires that \"meetings\" of a federal agency be open to the public. Section 552b(a)(2) defines a \"meeting\" as \"the deliberations of at least the number of individual agency members required to take action on behalf of the agency where such deliberations determine or result in the joint conduct or disposition of official agency business.\" Members of petitioner …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32, 37, 40","2":"28","3":"14"}},{"t":"case","label":"Keene Corp. v. United States","cite":"508 U.S. 200","y":1993,"id":"1992/92-166","sc":1,"sum":"Petitioner Keene Corporation has been sued by thousands of plaintiffs alleging injury from exposure to asbestos fibers and dust released from Keene products. Claiming that it was following Government specifications in including asbestos within products supplied to Government projects, and that it actually bought asbestos fiber from the Government, Keene filed two complaints against the United States in the Court of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Lambert Run Coal v. Baltimore & Ohio R.R.","cite":"258 U.S. 377","y":1922,"id":"scdb/1921-096","sc":1,"op":6,"ar":1,"by":{"1":"21, 22, 23, 34","2":"23","3":"14"}},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Lincoln v. Vigil","cite":"508 U.S. 182","y":1993,"id":"1992/91-1833","sc":1,"sum":"The Indian Health Service receives yearly lump-sum appropriations from Congress, and expends the funds under authority of the Snyder Act and the Indian Health Care Improvement Act to provide health care for American Indian and Alaska Native people. Out of these appropriations the Service funded, from 1978 to 1985, the Indian Children's Program (Program), which provided clinical services to handicapped Indian …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Lockerty v. Phillips","cite":"319 U.S. 182","y":1943,"id":"scdb/1942-149","sc":1,"sum":"1. The Emergency Price Control Act of 1942 sets up a procedure whereby any person subject to any regulation or order promulgated under the Act may on \"protest\" of the regulation or order secure its review by the Administrator; and, if the protest is denied, the Act confers on the Emergency Court (and on the Supreme Court upon review of decisions of the Emergency Court) equity jurisdicLOCKERTY v. PHILLIPS. Counsel …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"op":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16, 17, 47, 53","3":"2, 12"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"1":"20"}},{"t":"case","label":"Los Rovell Dahda v. United States","cite":"584 U.S. 440","y":2018,"url":"https://supreme.justia.com/cases/federal/us/584/440/","sc":1,"by":{"1":"11, 51"}},{"t":"case","label":"x Martin v. OSHA","cite":"499 U.S. 144","y":1991,"id":"1990/89-1541","sc":1,"sum":"A reviewing court should defer to the Secretary when the Secretary and the Commission furnish reasonable but conflicting interpretations of an ambiguous regulation promulgated by the Secretary under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49","3":"19"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith v. Manning","cite":"578 U.S. 374","y":2016,"id":"2015/14-1132","sc":1,"sum":"The Court determined that the Securities Exchange Act of 1934 creates the same test for establishing federal jurisdiction as the general test for whether a federal court has jurisdiction: Whether the case “arises under” federal law.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Mims v. Arrow Fin. Servs.","cite":"565 U.S. 368","y":2012,"id":"2011/10-1195","sc":1,"op":1,"sum":"The Court held that the Telephone Consumer Protection Act does not strip federal courts of the ability to hear cases that would normally be brought in state courts.","sumSrc":"Oyez","by":{"1":"33","2":"4"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"1":"52"}},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"op":1,"ar":1,"sum":"On a petition by a labor union for a representation election, the National Labor Relations Board (NLRB) held that the buyers employed by respondent company constituted an appropriate collective-bargaining unit and directed an election. The NLRB stated that even though the buyers might be \"managerial employees\" they were nevprtheless covered by the National Labor Relations Act (NLRA) in the absence of any showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Pac. Bell v. Pac. W. Telecomm","cite":"325 F.3d 1114","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/325/1114/","by":{"1":"38"}},{"t":"case","label":"Port of Boston Marine Terminal Ass’n v. Rederiaktiebolaget Transatlantic","cite":"400 U.S. 62","y":1970,"id":"1970/99","sc":1,"op":6,"sum":"Petitioner Terminal Association, a maritime terminal operators conference. operating under an agreement approved by the Federal Maritime Commission (FMC), pursuant to §.15 of the Shipping Act, 1916, revised a tariff on file with the agency by shifting the incidence of a wharf demuri'age charge from consignees to carriers. When several carriers refused to pay the revised charge, which -had not previously been …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 10, 29, 30, 31, 32, 34, 38, 40, 41, 42","2":"3, 8, 16-18, 23","3":"14"}},{"t":"case","label":"Port of Boston Marine Terminal Assn. v. Boston Shipping Assn., Inc.","cite":"420 F.2d 419","y":1970,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/420/419/","by":{"1":"30"}},{"t":"case","label":"xi Qwest Servs. Corp. v. FCC","cite":"509 F.3d 531","y":2007,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/509/531/","by":{"1":"48, 50"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"ar":1,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"1":"53"}},{"t":"case","label":"Stokeling v. United States","cite":"586 U.S. 73","y":2019,"id":"2018/17-5554","sc":1,"sum":"The Armed Career Criminal Act’s elements clause encompasses a robbery offense that, like Florida’s law, requires the criminal to overcome the victim’s resistance.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26","2":"20","3":"15"}},{"t":"case","label":"Tacoma v. Taxpayers of Tacoma","cite":"357 U.S. 320","y":1958,"id":"1957/509","sc":1,"sum":"The judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Talk America v. Mich. Bell Tel.","cite":"564 U.S. 50","y":2011,"id":"2010/10-313","sc":1,"sum":"The Court held that federal law requires local telephone companies to allow new competitors in their markets to link to their existing networks through connecting wires at low, government-regulated rates.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Thigpen v. Roberts","cite":"468 U.S. 27","y":1984,"id":"1983/82-1330","sc":1,"sum":"Following an accident in which he lost control of his car and collided with a pickup truck, killing a passenger in the truck, respondent was charged with four misdemeanors-reckless driving, driving while his license was revoked, driving on the wrong side of the road, and driving while intoxicated. Upon being convicted of these charges in a Mississippi Justice of the Peace Court, he appealed, and the case was …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"51"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17","2":"15","3":"6"}},{"t":"case","label":"Venner v. Mich. Cent. R.R.","cite":"271 U.S. 127","y":1926,"id":"scdb/1925-189","sc":1,"op":12,"ar":3,"by":{"1":"10, 20, 21, 22, 23","2":"23, 27","3":"13, 14"}},{"t":"case","label":"Woods v. Hills","cite":"334 U.S. 210","y":1948,"id":"scdb/1947-080","sc":1,"op":2,"sum":"Under § 205 of the Emergency Price Control Act, the Administrator brought anaction based on an alleged overcharge of rent. The issue, by stipulation of the parties, was the validity of the second of two orders of the Rent Director reducing maximum rents on property of the defendant. The District Court entered judgment for the defendant in 1946. An appeal by the Administrator was not submitted in the Circuit Court of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24, 25, 26, 28, 45","2":"20"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(6)","(7)"],"stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"head":"§551. Definitions","tname":"Government Organization and Employees","by":{"1":"6, 48","2":"21, 22, 26, 30, 30"}},{"t":"usc","label":"5 U.S.C. § 554","url":"https://www.law.cornell.edu/uscode/text/5/554","subs":["(e)"],"stext":{"head":"§554. Adjudications","paras":[[0,"(a) This section applies, according to the provisions thereof, in every case of adjudication required by statute to be determined on the record after opportunity for an agency hearing, except to the extent that there is involved—"],[1,"(1) a matter subject to a subsequent trial of the law and the facts de novo in a court;"],[1,"(2) the selection or tenure of an employee, except a 1 administrative law judge appointed under section 3105 of this title;"],[1,"(3) proceedings in which decisions rest solely on inspections, tests, or elections;"],[1,"(4) the conduct of military or foreign affairs functions;"],[1,"(5) cases in which an agency is acting as an agent for a court; or"],[1,"(6) the certification of worker representatives."],[0,"(b) Persons entitled to notice of an agency hearing shall be timely informed of—"],[1,"(1) the time, place, and nature of the hearing;"],[1,"(2) the legal authority and jurisdiction under which the hearing is to be held; and"],[1,"(3) the matters of fact and law asserted."],[0,"When private persons are the moving parties, other parties to the proceeding shall give prompt notice of issues controverted in fact or law; and in other instances agencies may by rule require responsive pleading. In fixing the time and place for hearings, due regard shall be had for the convenience and necessity of the parties or their representatives."],[0,"(c) The agency shall give all interested parties opportunity for—"],[1,"(1) the submission and consideration of facts, arguments, offers of settlement, or proposals of adjustment when time, the nature of the proceeding, and the public interest permit; and"],[1,"(2) to the extent that the parties are unable so to determine a controversy by consent, hearing and decision on notice and in accordance with sections 556 and 557 of this title."],[0,"(d) The employee who presides at the reception of evidence pursuant to section 556 of this title shall make the recommended decision or initial decision required by section 557 of this title, unless he becomes unavailable to the agency. Except to the extent required for the disposition of ex parte matters as authorized by law, such an employee may not—"],[1,"(1) consult a person or party on a fact in issue, unless on notice and opportunity for all parties to participate; or"],[1,"(2) be responsible to or subject to the supervision or direction of an employee or agent engaged in the performance of investigative or prosecuting functions for an agency."],[0,"An employee or agent engaged in the performance of investigative or prosecuting functions for an agency in a case may not, in that or a factually related case, participate or advise in the decision, recommended decision, or agency review pursuant to section 557 of this title, except as witness or counsel in public proceedings. This subsection does not apply—"],[1,"(A) in determining applications for initial licenses;"],[1,"(B) to proceedings involving the validity or application of rates, facilities, or practices of public utilities or carriers; or"],[1,"(C) to the agency or a member or members of the body comprising the agency."],[0,"(e) The agency, with like effect as in the case of other orders, and in its sound discretion, may issue a declaratory order to terminate a controversy or remove uncertainty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/554?type=usc&year=mostrecent&link-type=html"},"head":"§554. Adjudications","tname":"Government Organization and Employees","by":{"1":"6, 8, 48, 49, 50","2":"30"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"36"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"1":"32"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"1":"14","2":"15, 22","3":"6"}},{"t":"usc","label":"5 U.S.C. § 1031","url":"https://www.law.cornell.edu/uscode/text/5/1031","subs":["(1952)"],"by":{"1":"35"}},{"t":"usc","label":"7 U.S.C. § 499k","url":"https://www.law.cornell.edu/uscode/text/7/499k","by":{"1":"22"}},{"t":"usc","label":"15 U.S.C. § 78y","url":"https://www.law.cornell.edu/uscode/text/15/78y","stext":{"head":"§78y. Court review of orders and rules","paras":[[0,"(a) Final Commission orders; persons aggrieved; petition; record; findings; affirmance, modification, enforcement, or setting aside of orders; remand to adduce additional evidence"],[0,"(1) A person aggrieved by a final order of the Commission entered pursuant to this chapter may obtain review of the order in the United States Court of Appeals for the circuit in which he resides or has his principal place of business, or for the District of Columbia Circuit, by filing in such court, within sixty days after the entry of the order, a written petition requesting that the order be modified or set aside in whole or in part."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated by the Commission for that purpose. Thereupon the Commission shall file in the court the record on which the order complained of is entered, as provided in section 2112 of title 28 and the Federal Rules of Appellate Procedure."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the record, to affirm or modify and enforce or to set aside the order in whole or in part."],[0,"(4) The findings of the Commission as to the facts, if supported by substantial evidence, are conclusive."],[0,"(5) If either party applies to the court for leave to adduce additional evidence and shows to the satisfaction of the court that the additional evidence is material and that there was reasonable ground for failure to adduce it before the Commission, the court may remand the case to the Commission for further proceedings, in whatever manner and on whatever conditions the court considers appropriate. If the case is remanded to the Commission, it shall file in the court a supplemental record containing any new evidence, any further or modified findings, and any new order."],[0,"(b) Commission rules; persons adversely affected; petition; record; affirmance, enforcement, or setting aside of rules; findings; transfer of proceedings"],[0,"(1) A person adversely affected by a rule of the Commission promulgated pursuant to section 78f, 78i(h)(2), 78k, 78k–1, 78o(c)(5) or (6), 78o–3, 78q, 78q–1, or 78s of this title may obtain review of this rule in the United States Court of Appeals for the circuit in which he resides or has his principal place of business or for the District of Columbia Circuit, by filing in such court, within sixty days after the promulgation of the rule, a written petition requesting that the rule be set aside."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated for that purpose. Thereupon, the Commission shall file in the court the rule under review and any documents referred to therein, the Commission's notice of proposed rulemaking and any documents referred to therein, all written submissions and the transcript of any oral presentations in the rulemaking, factual information not included in the foregoing that was considered by the Commission in the promulgation of the rule or proffered by the Commission as pertinent to the rule, the report of any advisory committee received or considered by the Commission in the rulemaking, and any other materials prescribed by the court."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the materials set forth in paragraph (2) of this subsection, to affirm and enforce or to set aside the rule."],[0,"(4) The findings of the Commission as to the facts identified by the Commission as the basis, in whole or in part, of the rule, if supported by substantial evidence, are conclusive. The court shall affirm and enforce the rule unless the Commission's action in promulgating the rule is found to be arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law; contrary to constitutional right, power, privilege, or immunity; in excess of statutory jurisdiction, authority, or limitations, or short of statutory right; or without observance of procedure required by law."],[0,"(5) If proceedings have been instituted under this subsection in two or more courts of appeals with respect to the same rule, the Commission shall file the materials set forth in paragraph (2) of this subsection in that court in which a proceeding was first instituted. The other courts shall thereupon transfer all such proceedings to the court in which the materials have been filed. For the convenience of the parties in the interest of justice that court may thereafter transfer all the proceedings to any other court of appeals."],[0,"(c) Objections not urged before Commission; stay of orders and rules; transfer of enforcement or review proceedings"],[0,"(1) No objection to an order or rule of the Commission, for which review is sought under this section, may be considered by the court unless it was urged before the Commission or there was reasonable ground for failure to do so."],[0,"(2) The filing of a petition under this section does not operate as a stay of the Commission's order or rule. Until the court's jurisdiction becomes exclusive, the Commission may stay its order or rule pending judicial review if it finds that justice so requires. After the filing of a petition under this section, the court, on whatever conditions may be required and to the extent necessary to prevent irreparable injury, may issue all necessary and appropriate process to stay the order or rule or to preserve status or rights pending its review; but (notwithstanding section 705 of title 5) no such process may be issued by the court before the filing of the record or the materials set forth in subsection (b)(2) of this section unless: (A) the Commission has denied a stay or failed to grant requested relief, (B) a reasonable period has expired since the filing of an application for a stay without a decision by the Commission, or (C) there was reasonable ground for failure to apply to the Commission."],[0,"(3) When the same order or rule is the subject of one or more petitions for review filed under this section and an action for enforcement filed in a district court of the United States under section 78u(d) or (e) of this title, that court in which the petition or the action is first filed has jurisdiction with respect to the order or rule to the exclusion of any other court, and thereupon all such proceedings shall be transferred to that court; but, for the convenience of the parties in the interest of justice, that court may thereafter transfer all the proceedings to any other court of appeals or district court of the United States, whether or not a petition for review or an action for enforcement was originally filed in the transferee court. The scope of review by a district court under section 78u(d) or (e) of this title is in all cases the same as by a court of appeals under this section."],[0,"(d) Other appropriate regulatory agencies"],[0,"(1) For purposes of the preceding subsections of this section, the term \"Commission\" includes the agencies enumerated in section 78c(a)(34) of this title insofar as such agencies are acting pursuant to this chapter and the Secretary of the Treasury insofar as he is acting pursuant to section 78o–5 of this title."],[0,"(2) For purposes of subsection (a)(4) of this section and section 706 of title 5, an order of the Commission pursuant to section 78s(a) of this title denying registration to a clearing agency for which the Commission is not the appropriate regulatory agency or pursuant to section 78s(b) of this title disapproving a proposed rule change by such a clearing agency shall be deemed to be an order of the appropriate regulatory agency for such clearing agency insofar as such order was entered by reason of a determination by such appropriate regulatory agency pursuant to section 78s(a)(2)(C) or 78s(b)(4)(C) of this title that such registration or proposed rule change would be inconsistent with the safeguarding of securities or funds."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78y?type=usc&year=mostrecent&link-type=html"},"head":"§78y. Court review of orders and rules","tname":"Commerce and Trade","by":{"1":"19","2":"27"}},{"t":"usc","label":"28 U.S.C. § 1295","url":"https://www.law.cornell.edu/uscode/text/28/1295","by":{"1":"46"}},{"t":"usc","label":"28 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/28/2201","by":{"1":"15"}},{"t":"usc","label":"28 U.S.C. § 2348","url":"https://www.law.cornell.edu/uscode/text/28/2348","by":{"1":"1, 4","2":"21, 22, 26"}},{"t":"usc","label":"28 U.S.C. § 2350","url":"https://www.law.cornell.edu/uscode/text/28/2350","by":{"1":"1, 44"}},{"t":"usc","label":"47 U.S.C. § 155","url":"https://www.law.cornell.edu/uscode/text/47/155","subs":["(c)(1)","(c)(3)","(c)(4)","(c)(7)"],"by":{"1":"7","2":"4, 4, 4, 4"}},{"t":"law","label":"Pub. L. No. 100-430","url":"https://www.govinfo.gov/link/statute/102/1619","by":{"1":"32"}},{"t":"law","label":"Pub. L. No. 102-365","url":"https://www.govinfo.gov/link/statute/106/972","by":{"1":"33"}},{"t":"reg","label":"47 C.F.R. § 1.2","url":"https://www.ecfr.gov/current/title-47/section-1.2","by":{"1":"6, 48, 49"}},{"t":"case","label":"Alabama Power Co. v. FCC","cite":"311 F.3d 1357","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/311/1357/","by":{"2":"10"}},{"t":"case","label":"American Trucking Ass’n v. United States","cite":"755 F.2d 1292","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/755/1292/","ar":1,"by":{"2":"31"}},{"t":"case","label":"B&B Hardware, Inc. v. Hargis Indus., Inc.","cite":"575 U.S. 138","y":2015,"id":"2014/13-352","sc":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"2":"29, 32"}},{"t":"case","label":"CE Design, Ltd. v. Prism Bus. Media, Inc.","cite":"606 F.3d 443","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/606/443/","op":1,"by":{"2":"18"}},{"t":"case","label":"Caraco Pharm. Labs., Ltd. v. Novo Nordisk A/S","cite":"566 U.S. 399","y":2012,"id":"2011/10-844","sc":1,"sum":"The Court held that counterclaims that challenge unpatented uses of generic drugs, even if other approved uses are still under patent, are allowable under the Hatch-Waxman Act.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Cellular Phone Taskforce v. FCC","cite":"205 F.3d 82","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/205/82/","by":{"2":"10"}},{"t":"case","label":"City of Peoria v. General Elec. Cablevision Corp.","cite":"690 F.2d 116","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/690/116/","by":{"2":"18, 28"}},{"t":"case","label":"Daniels v. Union Pac. R.R.","cite":"530 F.3d 936","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/530/936/","op":1,"by":{"2":"18"}},{"t":"case","label":"International Telecard Ass’n v. FCC","cite":"166 F.3d 387","y":1999,"url":"https://www.courtlistener.com/c/F.3d/166/387/","by":{"2":"10, 11"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Jones v. Flowers","cite":"547 U.S. 220","y":2006,"id":"2005/04-1477","sc":1,"sum":"Therefore, the Court ruled that the government should have taken additional steps, such as remailing the notice or posting a notice on the house's door. Justice Thomas wrote a dissent, which was joined by Justices Scalia and Kennedy. Justice Alito took no part in the decision.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Leyse v. Clear Channel Broad., Inc.","cite":"545 Fed. Appx. 444","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./545/444/","by":{"2":"18"}},{"t":"case","label":"Nack v. Walburg","cite":"715 F.3d 680","y":2013,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/715/680/","op":1,"by":{"2":"18"}},{"t":"case","label":"Russell Motor Car Co. v. United States","cite":"261 U.S. 514","y":1923,"id":"scdb/1922-150","sc":1,"sum":"(a) The word “material” included anti-aircraft gun-mounts for the Navy.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"14","3":"8"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Sorenson Commc’ns, Inc. v. FCC","cite":"567 F.3d 1215","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/567/1215/","by":{"2":"31","3":"20"}},{"t":"case","label":"Thunder Basin Coal Co. v. Reich","cite":"510 U.S. 200","y":1994,"id":"1993/92-896","sc":1,"op":7,"sum":"Petitioner mine operator's nonunion work force designated two employees of the United Mine Workers of America (UMWA) to serve as miners' representatives under 30 U. S. C. §813(f). Claiming that the designations compromised its rights under the National Labor Relations Act (NLRA), petitioner refused to post information about the representatives as required by a regulation issued by the Department of Labor's Mine …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"United States v. Any & All Radio Station Transmission Equip.","cite":"207 F.3d 458","y":2000,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/207/458/","op":1,"by":{"2":"18, 28"}},{"t":"case","label":"United States v. Dunifer","cite":"219 F.3d 1004","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/219/1004/","op":1,"by":{"2":"18"}},{"t":"case","label":"United States v. Mendoza","cite":"464 U.S. 154","y":1984,"id":"1983/82-849","sc":1,"sum":"The United States may not be collaterally estopped on an issue such as the one involved here, adjudicated against it in an earlier lawsuit brought by a different party.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"United States v. Ruzicka","cite":"329 U.S. 287","y":1946,"id":"scdb/1946-018","sc":1,"sum":"They can not assert this defense in an enforcement proceeding under § 8a (6) but are left to the administrative remedy specifically provided by § 8c (15). Stark v. Wickard, 321 U. S. 288, differentiated. Pp. 290-296. 152 F. 2d 167, reversed. In a suit by the Government under § 8a (6) of the Agricultural Marketing Agreement Act of 1937 against certain handlers of milk to enforce their obligation to make payments into …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"op":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"8, 19, 29"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(b)(A)","(d)(2)"],"by":{"2":"30, 30, 30"}},{"t":"usc","label":"47 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/47/151","by":{"2":"22"}},{"t":"usc","label":"47 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/47/501","by":{"2":"4"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)"],"by":{"2":"2"}},{"t":"usc","label":"28 U.S.C. § 44","url":"https://www.law.cornell.edu/uscode/text/28/44","subs":["(1934)"],"by":{"2":"22"}},{"t":"usc","label":"42 U.S.C. § 5841","url":"https://www.law.cornell.edu/uscode/text/42/5841","by":{"2":"2"}},{"t":"usc","label":"50 U.S.C. § 167h","url":"https://www.law.cornell.edu/uscode/text/50/167h","subs":["(b)"],"by":{"2":"2"}},{"t":"case","label":"ALDF v. U.S. Department of Agriculture","cite":"935 F.3d 858","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/935/858/","by":{"3":"7"}},{"t":"case","label":"Beneli v. National Labor Relations Board","cite":"873 F.3d 1094","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/873/1094/","sum":"Holding that the APA “allows an agency to declare interpretive rules in adjudication”.","sumSrc":"brief:3","by":{"3":"19"}},{"t":"case","label":"Central Texas Telephone Co-op., Inc. v. FCC","cite":"402 F.3d 205","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/402/205/","op":2,"by":{"3":"20"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"General Dynamics Land Systems, Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Marbury v. Madison","cite":"5 U.S. 137","y":1803,"id":"1789-1850/5us137","sc":1,"sum":"A case in which the Court established a precedent for judicial review in the United States, declaring that acts of Congress that conflict with the Constitution are null and void, as the Constitution is the supreme law of the land.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"McBoyle v. United States","cite":"283 U.S. 25","y":1931,"id":"scdb/1930-139","sc":1,"sum":"The National Motor Vehicle Theft Act, U. S. C., Title 18, § 408, which punishes whoever transports, or causes to be transported, in interstate or foreign commerce a motor vehicle knowing it to have been stolen, and which defines \"motor vehicle\" as including \"an automobile, automobile truck, automobile wagon, motor cycle, or any other self-propelled vehicle not designed for running on rails,\" does not apply to …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"4"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Environment","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"United States v. Naftalin","cite":"441 U.S. 768","y":1979,"id":"1978/78-561","sc":1,"sum":"Section 17 (a) (1) prohibits frauds against brokers as well as investors.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"7"}},{"t":"case","label":"Viacom International Inc. v. FCC","cite":"672 F.2d 1034","y":1982,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/672/1034/","sum":"Holding that the “interpretation of regulations by declaratory ruling” in an adjudication falls “well within the scope of the familiar power of an agency”.","sumSrc":"brief:3","by":{"3":"20"}},{"t":"case","label":"-v- Whitney National Bank v. Bank of New Orleans & Trust Co.","cite":"379 U.S. 411","y":1965,"id":"1964/26","sc":1,"sum":"A New Orleans-based national bank, desiring to expand but prohibited from operating branches beyond its home parish, formed a holding company which in turn organized a new national bank to operate in an adjoining parish. Pursuant to the Bank Holding Company Act of 1956, the Federal Reserve Board (FRB), after receiving favorable advice from the Comptroller of the Currency (Comptroller), held hearings on the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"rule","label":"Fed. R. Civ. P. 58","url":"https://www.law.cornell.edu/rules/frcp/rule_58","by":{"3":"10"}}]};